import test from 'node:test';
import assert from 'node:assert/strict';
import {
  compare,
  normalizeSource,
  safeSum,
} from '../lib/reconciliation/core.ts';
import { defaultMapping } from '../lib/reconciliation/types.ts';
import type {
  Comparison,
  Mapping,
  Scope,
  SourceFile,
  SourceResult,
} from '../lib/reconciliation/types.ts';
import { separateSheets } from './helpers/separate-export.ts';

// Independent synthetic accounting expectations: no fixture or expected result
// is generated by the matching implementation or by the private July examples.
const scope: Scope = {
  supplier: 'Synthetic Supplier',
  entity: 'Synthetic Entity',
  account: 'TEST-701',
  currency: 'SAR',
  decimals: 2,
  cutoff: '2026-09-30',
  dateWindow: 3,
  confirmed: true,
  coverageConfirmed: false,
};
const headers = [
  'Date',
  'Invoice No',
  'Document Type',
  'AP Voucher',
  'PO',
  'Bank Ref',
  'Description',
  'Amount',
  'Currency',
];
const mapping: Mapping = {
  ...defaultMapping(),
  date: 0,
  reference: 1,
  description: 6,
  amount: 7,
  currencyColumn: 8,
  opening: '',
  closing: '',
  periodStart: '',
};
type Row = {
  ref: string;
  amount: string;
  date?: string;
  type?: string;
  voucher?: string;
  po?: string;
  bank?: string;
  description?: string;
  currency?: string;
};
function file(rows: Row[], heading = headers): SourceFile {
  return {
    name: 'synthetic-diversity.csv',
    sheets: [
      {
        name: 'Transactions',
        formulaRows: [],
        hiddenRows: [],
        rows: [
          heading,
          ...rows.map((r) => [
            r.date ?? '2026-09-12',
            r.ref,
            r.type ?? 'Invoice',
            r.voucher ?? '',
            r.po ?? '',
            r.bank ?? '',
            r.description ?? '',
            r.amount,
            r.currency ?? 'SAR',
          ]),
        ],
      },
    ],
  };
}
function sources(a: Row[], b: Row[], s = scope): [SourceResult, SourceResult] {
  return [
    normalizeSource(file(a), mapping, s, 'supplier'),
    normalizeSource(separateSheets(file(b)), mapping, s, 'ledger'),
  ];
}
function run(a: Row[], b: Row[], s = scope) {
  const pair = sources(a, b, s);
  assert.deepEqual(
    pair.flatMap((p) => p.errors),
    [],
  );
  const result = compare(...pair, s);
  conserved(result);
  return result;
}
function conserved(r: Comparison) {
  const original = [...r.supplier.transactions, ...r.ledger.transactions];
  const members = r.cases.flatMap((c) => [
    ...c.supplierMembers,
    ...c.ledgerMembers,
  ]);
  assert.deepEqual(
    members.map((m) => m.id).sort(),
    original.map((m) => m.id).sort(),
  );
  assert.equal(new Set(members.map((m) => m.id)).size, original.length);
  assert.equal(safeSum(r.cases.map((c) => c.supplierTotal)), r.supplier.total);
  assert.equal(safeSum(r.cases.map((c) => c.ledgerTotal)), r.ledger.total);
  assert.equal(
    safeSum(r.cases.map((c) => c.bridgeEffect)),
    safeSum([r.ledger.total, -r.supplier.total]),
  );
  for (const c of r.cases) {
    assert.equal(
      c.sourceTrace.length,
      c.supplierMembers.length + c.ledgerMembers.length,
    );
    if (c.status === 'Matched') assert.equal(c.variance, 0);
  }
}
function signature(r: Comparison) {
  const economic = (s: SourceResult['transactions']) =>
    s
      .map((t) =>
        [
          t.reference,
          t.date,
          t.amount,
          t.description,
          t.documentType,
          t.voucherReference,
          t.poReference,
        ].join('|'),
      )
      .sort();
  return r.cases
    .map((c) =>
      JSON.stringify([
        c.status,
        c.classification,
        economic(c.supplierMembers),
        economic(c.ledgerMembers),
        c.variance,
      ]),
    )
    .sort();
}
function permutations<T>(rows: T[]): T[][] {
  return rows.length < 2
    ? [rows]
    : rows.flatMap((v, i) =>
        permutations(rows.filter((_, j) => j !== i)).map((rest) => [
          v,
          ...rest,
        ]),
      );
}

test('known contradictory document types never auto-match equal signed amounts and exact references', () => {
  for (const [a, b] of [
    ['Invoice', 'Credit Note'],
    ['Invoice', 'Payment'],
    ['Invoice', 'Journal'],
    ['Credit Note', 'Payment'],
  ]) {
    const r = run(
      [{ ref: 'DOC-7001', amount: '143.27', type: a }],
      [{ ref: 'DOC-7001', amount: '143.27', type: b }],
    );
    assert.equal(r.matches.length, 0, `${a} versus ${b}`);
    assert.equal(
      r.caseCounts.needsReviewCases,
      1,
      'the contradiction is visible for review',
    );
  }
  const bilingual = [...headers];
  bilingual[2] = 'Type / النوع';
  bilingual[4] = 'PO | أمر الشراء';
  const a = normalizeSource(
    file(
      [{ ref: 'DOC-7001', amount: '143.27', type: 'Invoice', po: 'PO-710' }],
      bilingual,
    ),
    mapping,
    scope,
    'supplier',
  );
  const b = normalizeSource(
    file(
      [{ ref: 'DOC-7001', amount: '143.27', type: 'Payment', po: 'PO-720' }],
      bilingual,
    ),
    mapping,
    scope,
    'ledger',
  );
  assert.equal(a.transactions[0].documentType, 'Invoice');
  assert.equal(b.transactions[0].documentType, 'Payment');
  assert.equal(a.transactions[0].poReference, 'PO-710');
  assert.equal(compare(a, b, scope).matches.length, 0);
  for (const type of ['Return', 'Debit Memo', 'Unrecognized accounting type']) {
    const r = run(
      [{ ref: 'DOC-UNKNOWN-18', amount: '143.27', type }],
      [{ ref: 'DOC-UNKNOWN-18', amount: '143.27' }],
    );
    assert.equal(r.matches.length, 0);
    assert.ok(r.supplier.transactions[0].referenceEvidenceIssues?.length);
  }
  assert.equal(
    run(
      [{ ref: 'DOC-NO-TYPE-18', amount: '143.27', type: '' }],
      [{ ref: 'DOC-NO-TYPE-18', amount: '143.27', type: '' }],
    ).matches.length,
    1,
    'a genuinely missing type remains supported by strict reference/amount/date proof',
  );
});

test('contradictory explicit PO evidence blocks auto-match while ordinary internal voucher differences do not', () => {
  const a = [
    { ref: 'INV-8201', amount: '713.11', po: 'PO-410', voucher: 'SUP-731' },
  ];
  const b = [
    { ref: 'INV-8201', amount: '713.11', po: 'PO-420', voucher: 'ERP-942' },
  ];
  const conflict = run(a, b);
  assert.equal(conflict.matches.length, 0);
  assert.equal(conflict.caseCounts.needsReviewCases, 1);
  assert.equal(
    run(a, [{ ...b[0], po: 'PO-410' }]).matches.length,
    1,
    'different internal voucher namespaces are normal',
  );
});

test('a mapped invoice reference is not replaced by an unrelated common PO', () => {
  const h = [...headers];
  h[1] = 'Reference';
  const a = normalizeSource(
    file([{ ref: 'INV-ALPHA-71', amount: '400', po: 'PO-COMMON-88' }], h),
    mapping,
    scope,
    'supplier',
  );
  const b = normalizeSource(
    file([{ ref: 'INV-BETA-93', amount: '400', po: 'PO-COMMON-88' }], h),
    mapping,
    scope,
    'ledger',
  );
  assert.equal(a.transactions[0].reference, 'INV-ALPHA-71');
  assert.equal(b.transactions[0].reference, 'INV-BETA-93');
  const r = compare(a, b, scope);
  assert.equal(r.matches.length, 0);
  conserved(r);
});

test('PO-only identity remains visible but cannot certify one invoice or a group of invoices', () => {
  for (const [a, b] of [
    [
      [{ ref: '', amount: '92', po: 'PO-740' }],
      [{ ref: '', amount: '92', po: 'PO-740' }],
    ],
    [
      [{ ref: '', amount: '92', po: 'PO-740' }],
      [
        { ref: '', amount: '40', po: 'PO-740' },
        { ref: '', amount: '52', po: 'PO-740' },
      ],
    ],
  ] as [Row[], Row[]][]) {
    const r = run(a, b);
    assert.equal(r.matches.length, 0);
    assert.ok(r.supplier.transactions[0].referenceEvidenceIssues?.length);
  }
});

test('identical repeated posting lines cannot be proved distinct by their sum', () => {
  const single = [{ ref: 'INV-DUP-80', amount: '184', po: 'PO-388' }];
  const repeated = Array.from({ length: 2 }, () => ({
    ref: 'INV-DUP-80',
    amount: '92',
    po: 'PO-388',
    voucher: 'AP-399',
    description: 'same posting evidence',
  }));
  for (const [a, b] of [
    [single, repeated],
    [repeated, single],
  ]) {
    const r = run(a, b);
    assert.equal(r.matches.length, 0);
    assert.equal(r.caseCounts.needsReviewCases, 1);
    assert.equal(r.caseCounts.needsReviewSourceRows, 3);
  }
});

test('valid positive and negative whole-reference groups match in either direction without subset search', () => {
  for (const sign of [1, -1])
    for (const reverse of [false, true]) {
      const type = sign === 1 ? 'Invoice' : 'Credit Note';
      const single = [
        { ref: 'DOC-GRP-81', amount: String(sign * 184), type, po: 'PO-387' },
      ];
      const group = [
        {
          ref: 'DOC-GRP-81',
          amount: String(sign * 80),
          type,
          po: 'PO-387',
          voucher: 'AP-711',
        },
        {
          ref: 'DOC-GRP-81',
          amount: String(sign * 104),
          type,
          po: 'PO-387',
          voucher: 'AP-711',
        },
      ];
      const r = run(
        ...((reverse ? [group, single] : [single, group]) as [Row[], Row[]]),
      );
      assert.equal(r.caseCounts.autoMatchedCases, 1);
      assert.equal(r.caseCounts.matchedSourceRows, 3);
      assert.equal(
        r.cases[0].classification,
        reverse ? 'EXACT_MANY_TO_1' : 'EXACT_1_TO_MANY',
      );
    }
});

test('one-to-many proof fails with altered amount, date, type, PO, voucher or unreadable identity', () => {
  const single = [{ ref: 'INV-MUT-81', amount: '184', po: 'PO-387' }];
  const group = [
    { ref: 'INV-MUT-81', amount: '80', po: 'PO-387', voucher: 'AP-711' },
    { ref: 'INV-MUT-81', amount: '104', po: 'PO-387', voucher: 'AP-711' },
  ];
  for (const mutation of [
    { amount: '104.01' },
    { date: '2026-09-13' },
    { type: 'Payment' },
    { po: 'PO-OTHER-88' },
    { voucher: 'AP-OTHER-98' },
  ]) {
    const r = run(single, [group[0], { ...group[1], ...mutation }]);
    assert.equal(r.matches.length, 0, JSON.stringify(mutation));
  }
  const pair = sources(single, group);
  pair[1].transactions[1].referenceEvidenceIssues = ['unreadable PO'];
  assert.equal(compare(...pair, scope).matches.length, 0);
  pair[1].transactions[1].referenceEvidenceIssues = [];
  pair[0].errors.push({
    row: 99,
    message: 'Unreadable movement may duplicate a reference',
  });
  assert.equal(compare(...pair, scope).matches.length, 0);
});

test('mixed signs, competing whole groups and subset coincidences never produce a group match', () => {
  for (const [a, b] of [
    [
      [{ ref: 'INV-SUB-54', amount: '100', po: 'PO-87' }],
      [
        { ref: 'INV-SUB-54', amount: '150', po: 'PO-87' },
        { ref: 'INV-SUB-54', amount: '-50', po: 'PO-87' },
      ],
    ],
    [
      [{ ref: 'INV-SUB-54', amount: '100', po: 'PO-87' }],
      [
        { ref: 'INV-SUB-54', amount: '40', po: 'PO-87' },
        { ref: 'INV-SUB-54', amount: '60', po: 'PO-87' },
        { ref: 'INV-SUB-54', amount: '10', po: 'PO-87' },
      ],
    ],
    [
      [
        { ref: 'INV-SUB-54', amount: '100', po: 'PO-87' },
        { ref: 'INV-SUB-54', amount: '40', po: 'PO-87' },
      ],
      [
        { ref: 'INV-SUB-54', amount: '90', po: 'PO-87' },
        { ref: 'INV-SUB-54', amount: '50', po: 'PO-87' },
      ],
    ],
  ] as [Row[], Row[]][])
    assert.equal(run(a, b).matches.length, 0);
});

test('currency from another normalized scope cannot be compared, including manual decisions', () => {
  const a = sources(
    [{ ref: 'INV-FX-01', amount: '100' }],
    [{ ref: 'INV-FX-01', amount: '100' }],
  )[0];
  const otherScope = { ...scope, currency: 'USD' };
  const b = normalizeSource(
    file([{ ref: 'INV-FX-01', amount: '100', currency: 'USD' }]),
    mapping,
    otherScope,
    'ledger',
  );
  assert.deepEqual(b.errors, []);
  assert.throws(() => compare(a, b, scope), /عملة|currency/i);
  assert.throws(
    () =>
      compare(a, b, scope, [
        {
          supplierId: a.transactions[0].id,
          ledgerId: b.transactions[0].id,
          note: 'reviewed',
        },
      ]),
    /عملة|currency/i,
  );
  const usdA = normalizeSource(
    file([{ ref: 'INV-FX-01', amount: '100', currency: 'USD' }]),
    mapping,
    otherScope,
    'supplier',
  );
  assert.throws(
    () => compare(usdA, b, scope),
    /عملة|currency/i,
    'pairwise equality is insufficient when the whole scope has changed',
  );
  for (const declarations of [
    [['Currency', 'USD']],
    [
      ['Currency', 'SAR'],
      ['Currency', 'USD'],
    ],
  ]) {
    const f = file([{ ref: 'INV-FX-01', amount: '100' }]);
    f.sheets[0].rows.unshift(...declarations);
    const source = normalizeSource(
      f,
      { ...mapping, header: declarations.length },
      scope,
      'supplier',
    );
    assert.ok(source.errors.some((e) => /عملة/.test(e.message)));
    if (source.metadata?.currency === 'USD') {
      assert.equal(
        source.transactions.length,
        0,
        'A foreign-currency amount is not relabelled with the confirmed currency',
      );
      assert.ok(source.errors.some((e) => e.row === declarations.length + 2));
      assert.ok(
        f.sheets[0].rows.at(-1)?.includes('INV-FX-01'),
        'The original source remains available for review',
      );
      assert.throws(
        () =>
          compare(
            source,
            sources(
              [{ ref: 'INV-FX-01', amount: '100' }],
              [{ ref: 'INV-FX-01', amount: '100' }],
            )[1],
            scope,
          ),
        /حركات كافية/,
      );
      continue;
    }
    assert.equal(
      source.transactions.length,
      1,
      'A conflicting declaration remains flagged and cannot authorize a match',
    );
    const result = compare(
      source,
      sources(
        [{ ref: 'INV-FX-01', amount: '100' }],
        [{ ref: 'INV-FX-01', amount: '100' }],
      )[1],
      scope,
    );
    assert.equal(
      result.matches.length,
      0,
      'explicit metadata conflict prevents automatic matching',
    );
    conserved(result);
  }
  for (const label of [
    'Amount (SAR) / المبلغ (USD)',
    'Amount (USD) / المبلغ (SAR)',
  ]) {
    const h = [...headers];
    h[7] = label;
    assert.throws(
      () =>
        normalizeSource(
          file([{ ref: 'INV-FX-01', amount: '100' }], h),
          mapping,
          scope,
          'supplier',
        ),
      /عملة/,
    );
  }
});

test('date boundaries, signed zero and reference punctuation do not silently broaden identity', () => {
  const a = [{ ref: 'INV-DATE-55', amount: '178.31', date: '2026-09-10' }];
  assert.equal(run(a, [{ ...a[0], date: '2026-09-13' }]).matches.length, 1);
  assert.equal(run(a, [{ ...a[0], date: '2026-09-14' }]).matches.length, 0);
  assert.equal(run(a, [{ ...a[0], ref: 'INVDATE55' }]).matches.length, 0);
  assert.equal(run(a, [{ ...a[0], amount: '-178.31' }]).matches.length, 0);
  assert.equal(
    run([{ ...a[0], amount: '0' }], [{ ...a[0], amount: '-0' }]).matches.length,
    0,
  );
});

test('unique payment amount with different references remains review-only under every row permutation', () => {
  const a = [
    {
      ref: 'RCPT-760',
      amount: '-731.13',
      type: 'Payment',
      description: 'Bank transfer received',
    },
    { ref: 'INV-S-A7', amount: '831.12' },
  ];
  const b = [
    {
      ref: 'AP-PAY-820',
      amount: '-731.13',
      type: 'Payment',
      bank: 'BANK-876',
      description: 'Bank payment sent',
    },
    { ref: 'INV-L-B8', amount: '823.41' },
  ];
  for (const left of permutations(a))
    for (const right of permutations(b)) {
      const r = run(left, right);
      assert.equal(r.matches.length, 0);
      assert.equal(
        r.cases.filter((c) => c.classification === 'PAYMENT_CANDIDATE').length,
        1,
      );
      assert.equal(r.caseCounts.needsReviewCases, 1);
    }
  const duplicateAmount = run(a, [
    ...b,
    { ref: 'INV-UNRELATED-21', amount: '-731.13' },
  ]);
  assert.equal(
    duplicateAmount.cases.filter(
      (c) => c.classification === 'PAYMENT_CANDIDATE',
    ).length,
    0,
  );
});

test('classification and row conservation are invariant under 864 independent source permutations', () => {
  const a = [
    { ref: 'INV-EXACT-11', amount: '109.17' },
    { ref: 'INV-GROUP-19', amount: '731.14', po: 'PO-567' },
    { ref: 'INV-ONLY-91', amount: '21.30' },
  ];
  const b = [
    { ref: 'INV-EXACT-11', amount: '109.17' },
    { ref: 'INV-GROUP-19', amount: '330.11', po: 'PO-567', voucher: 'AP-833' },
    { ref: 'INV-GROUP-19', amount: '401.03', po: 'PO-567', voucher: 'AP-833' },
    { ref: 'INV-ONLY-88', amount: '18.01' },
  ];
  const expected = signature(run(a, b));
  let checks = 0;
  for (const left of permutations(a))
    for (const right of permutations(b))
      for (const window of [0, 1, 2, 3, 5, 7]) {
        assert.deepEqual(
          signature(run(left, right, { ...scope, dateWindow: window })),
          expected,
        );
        checks++;
      }
  assert.equal(checks, 864);
});

test('exact minor units remain conserved for all supported scales and arithmetic limits reject overflow', () => {
  for (const decimals of [0, 2, 3]) {
    const unit = 10 ** decimals;
    const amount = decimals === 0 ? '91' : decimals === 2 ? '91.07' : '91.007';
    const r = run(
      [{ ref: 'INV-UNIT-07', amount }],
      [{ ref: 'INV-UNIT-07', amount }],
      { ...scope, decimals },
    );
    assert.equal(r.supplier.total, 91 * unit + (decimals === 0 ? 0 : 7));
    assert.equal(r.matches.length, 1);
  }
  assert.throws(() => safeSum([1e14, 1]));
  const s = { ...scope, decimals: 0 };
  const pair = sources(
    [{ ref: 'INV-LIMIT-A1', amount: '100000000000000' }],
    [{ ref: 'INV-LIMIT-B1', amount: '-100000000000000' }],
    s,
  );
  for (const source of pair) {
    source.opening = 0;
    source.closing = source.total;
    source.balanceArithmeticStatus = 'BALANCE_ARITHMETIC_VERIFIED';
    source.mapping = { ...source.mapping, periodStart: '2026-09-01' };
  }
  assert.throws(() => compare(...pair, s));
});

test('repeated headers with formula, hidden or unreadable cells cannot silently leave the transaction population', () => {
  const clean = file([{ ref: 'INV-REPEAT-88', amount: '113.19' }]);
  clean.sheets[0].rows.push([...headers]);
  const benign = normalizeSource(clean, mapping, scope, 'supplier');
  assert.equal(benign.errors.length, 0);
  assert.ok(benign.excluded.some((e) => e.row === 3 && /مُكرر/.test(e.reason)));
  for (const mutate of [
    (f: SourceFile) => {
      f.sheets[0].formulaRows = [3];
      f.sheets[0].cellIssues = { '3:8': ['صيغة Excel في H3'] };
    },
    (f: SourceFile) => {
      f.sheets[0].cellIssues = { '3:7': ['unreadable helper header'] };
    },
    (f: SourceFile) => {
      f.sheets[0].referenceIssues = { '3:7': ['ambiguous helper reference'] };
    },
    (f: SourceFile) => {
      f.sheets[0].hiddenRows = [3];
    },
    (f: SourceFile) => {
      f.sheets[0].rowIssues = { '3': ['نص يعبر حد عمود؛ unsafe header'] };
    },
  ]) {
    const f = structuredClone(clean);
    mutate(f);
    const source = normalizeSource(f, mapping, scope, 'supplier');
    assert.ok(
      source.errors.some((e) => e.row === 3),
      'untrusted header-like row must remain an explicit error',
    );
    assert.ok(!source.excluded.some((e) => e.row === 3));
  }
});

test('overlapping rejected edges never choose arbitrary partners under source or decision permutations', () => {
  const a = [
    { ref: 'INV-REJECT-S1', amount: '71.93' },
    { ref: 'INV-REJECT-S2', amount: '71.93' },
  ];
  const b = [
    { ref: 'INV-REJECT-L1', amount: '71.93' },
    { ref: 'INV-REJECT-L2', amount: '71.93' },
  ];
  const edges = [
    [a[0].ref, b[0].ref],
    [a[0].ref, b[1].ref],
    [a[1].ref, b[0].ref],
  ];
  let expected: string[] | undefined;
  let checks = 0;
  for (const left of permutations(a))
    for (const right of permutations(b))
      for (const order of permutations(edges)) {
        const pair = sources(left, right);
        const rejections = order.map(
          ([s, l]) =>
            `${pair[0].transactions.find((t) => t.reference === s)!.id}|${pair[1].transactions.find((t) => t.reference === l)!.id}`,
        );
        const r = compare(...pair, scope, [], rejections);
        conserved(r);
        assert.equal(r.matches.length, 0);
        assert.equal(
          r.caseCounts.rejectedCandidates,
          0,
          'overlapping decisions reject edges but do not establish a pairing',
        );
        assert.equal(r.caseCounts.unmatchedSourceRows, 4);
        assert.deepEqual(
          r.rejectedPairs,
          rejections,
          'all original review decisions remain recorded',
        );
        expected ??= signature(r);
        assert.deepEqual(signature(r), expected);
        checks++;
      }
  assert.equal(checks, 24);
  const pair = sources([a[0]], [b[0]]);
  const isolated = compare(
    ...pair,
    scope,
    [],
    [`${pair[0].transactions[0].id}|${pair[1].transactions[0].id}`],
  );
  assert.equal(
    isolated.caseCounts.rejectedCandidates,
    1,
    'an isolated rejected edge remains a rejected case',
  );
  conserved(isolated);
});
